from lib import *
S = SS('w93')
steps = [
    step("TLS 1.3 的会话恢复:第一次完整握手并读完响应(这样服务器握手后发的 session ticket 才会被收到),第二次带着这个 session 做恢复(PSK)。各 5 对。完整握手耗时 [807, 155, 802, 166, 175] ms,中位 175 ms(有两次被网络抖动拉到 800 ms 左右);恢复握手 [169, 1503, 169, 154, 600] ms,中位 169 ms,5 次 session_reused 全是 True。耗时几乎一样——TLS 1.3 的完整握手本来就只有一个往返,恢复省不掉这个往返。省下的是字节:服务器→客户端的字节数,完整握手中位 6563,恢复握手中位 2800(含各一次 HTTP 响应);客户端→服务器反而从 1689 增加到 1960,因为恢复的 ClientHello 要多带 ticket。Python 的 session 对象 has_ticket = True,它自己记录的生存期是 7200 秒(服务器在 ticket 里通告的是 64800 秒,见第五节)。", t=tl(S(1)), mark=lidx(S(1), '完整握手:耗时', '恢复握手:耗时'), done=lidx(S(1), 'session 对象'), b=bars([['完整握手 服务器→客户端', 6563, '6563 字节'], ['恢复握手 服务器→客户端', 2800, '2800 字节'], ['完整握手 耗时', 175, '175 ms'], ['恢复握手 耗时', 169, '169 ms']], 6563, mark=[1], done=[0, 2, 3]), kv=KV([['握手耗时', '完整 175 ms / 恢复 169 ms(都是 1 个往返)'], ['服务器→客户端字节', '6563 → 2800'], ['恢复成功', '5 / 5 次 session_reused']], ['服务器→客户端字节'])),
    step("恢复的握手在线上长什么样。完整握手的 ClientHello 1526 字节;恢复握手的 ClientHello 1797 字节,扩展列表多了最后一个 pre_shared_key(267 字节,里面是 ticket 本身加一个 binder,用来证明客户端确实知道会话密钥;规范要求它必须是最后一个扩展)。ServerHello 的扩展:完整握手是 [key_share, supported_versions],恢复握手多一个 pre_shared_key——表示服务器接受了恢复。ServerHello 之后的加密记录:完整握手 [3859, 477, 940, 22, 19] 字节,恢复握手 [90, 477, 940, 22, 19]——完整握手里那个 3859 字节的记录装的是证书链,恢复时不再发证书,只剩 90 字节的小记录。(后面的 477、940、22、19 是什么记录,我没有解密确认,推测是握手之后的 NewSessionTicket 和应用数据。)", t=tl(S(2)), mark=lidx(S(2), '恢复握手的 ClientHello', '恢复握手的 ServerHello 扩展'), done=lidx(S(2), '完整握手的 ClientHello', '服务器在 ServerHello 之后发的加密记录'), b=bars([['完整握手 证书那个记录', 3859, '3859 字节'], ['恢复握手 对应的记录', 90, '90 字节']], 3859, mark=[1], done=[0]), kv=KV([['ClientHello', '1526 → 1797 字节(多 pre_shared_key 267 字节)'], ['ServerHello', '多 pre_shared_key,表示接受恢复'], ['证书', '恢复时不再发']], ['证书'])),
    step("TLS 1.2 的会话恢复(session ticket)。限定 TLS 1.2,各 5 对:完整握手 [327, 891, 322, 306, 319] ms,中位 322 ms;恢复握手 [157, 155, 154, 163, 153] ms,中位 155 ms,5 次全部恢复成功。TLS 1.2 的完整握手要 2 个往返,恢复后只要 1 个,耗时正好减半(322 → 155 ms)。对比 TLS 1.3:完整 175 ms、恢复 169 ms——TLS 1.3 的完整握手已经只要一个往返,所以恢复省的是证书和计算,不再省往返。", t=tl(S(3)), mark=lidx(S(3), 'TLS 1.2 完整握手', '对比 TLS 1.3'), done=lidx(S(3), 'TLS 1.2 完整握手'), b=bars([['TLS 1.2 完整', 322, '322 ms'], ['TLS 1.2 恢复', 155, '155 ms'], ['TLS 1.3 完整', 175, '175 ms'], ['TLS 1.3 恢复', 169, '169 ms']], 322, mark=[1], done=[0, 2, 3]), kv=KV([['TLS 1.2', '完整 322 ms → 恢复 155 ms(省 1 个往返)'], ['TLS 1.3', '完整 175 ms → 恢复 169 ms(没有省往返)']], ['TLS 1.2'])),
    step("ticket 能用几次?同一个 session 对象连续恢复 4 次:每次 session_reused 都是 True,握手 166、190、162、162 ms。也就是说这个服务器接受重复使用同一个 ticket。TLS 1.3 规范建议每个 ticket 只用一次(防重放和跨连接关联),并让服务器对每次握手发新的 ticket;这里的客户端(Python)一直拿第一个 session 重用,服务器也没有拒绝。这意味着同一个 ticket 在多个连接里出现,路径上的观察者可以把这些连接关联起来(ticket 是明文发在 ClientHello 里的 identity)。", t=tl(S(4)), mark=lidx(S(4), '连续 4 次用同一个 ticket'), done=lidx(S(4), 'TLS 1.3 规范建议'), kv=KV([['连续 4 次同一个 ticket', '全部恢复成功'], ['风险', 'ticket 重复出现可关联连接']], ['风险'])),
    step("0-RTT(早期数据):恢复握手时,客户端在第一个包里就带上应用数据,省掉整个握手往返,代价是可被重放。用 openssl s_client 实测 example.com:第一次连接收到 2 个 NewSessionTicket,每个都是 “ticket lifetime hint: 64800 秒(18 小时)”和 “Max Early Data: 0”。第二次带着 ticket 并要求发 early data:Reused, TLSv1.3, Cipher is TLS_AES_256_GCM_SHA384,但 “Early data was not sent”。Max Early Data 为 0 表示服务器没有允许 0-RTT,所以恢复成功了,早期数据却没有发出——这个站点关闭了 0-RTT。因此 0-RTT 的收益和重放风险,我在这里没有实际测到。", t=tl(S(5)), mark=lidx(S(5), '第一次连接(openssl)', '第二次(带 ticket'), done=lidx(S(5), '服务器收到了'), kv=KV([['ticket 生存期提示', '64800 秒(18 小时)'], ['Max Early Data', '0(不允许 0-RTT)'], ['带 early data 的恢复', 'Reused,但 Early data was not sent']], ['Max Early Data'])),
]
A = mkartw('w93', 93, '网络协议,TLS,会话恢复,PSK,session ticket,0-RTT,真实验证,动画演示',
    '实测 TLS 会话恢复:TLS 1.3 恢复握手耗时与完整握手几乎相同(169 对 175 ms)但服务器→客户端字节从 6563 降到 2800(不再发证书),ClientHello 多 267 字节的 pre_shared_key;TLS 1.2 恢复省一个往返(322 → 155 ms);同一 ticket 重复用 4 次都成功;example.com 的 Max Early Data 为 0,0-RTT 没有测成。',
    '每次 HTTPS 连接都做完整握手太浪费:TLS 的会话恢复让客户端带着上次的“票”回来。这篇测它省了什么(1.2 里是一个往返,1.3 里是证书和计算,不是往返)、ClientHello 里多了什么、ticket 能用几次,以及传说中的 0-RTT 在真实服务器上到底开不开。',
    [('6563 → 2800 字节', 'TLS 1.3 完整握手与恢复握手里服务器→客户端的字节数(中位)'), ('322 → 155 ms', 'TLS 1.2 完整握手与恢复握手的耗时中位数,恰好省一个往返'), ('Max Early Data: 0', 'example.com 的 ticket 里允许的早期数据量:0-RTT 被关闭')],
    [('1.3 恢复省什么', '<p>省证书和计算,不省往返:耗时 175 对 169 ms,但服务器→客户端字节降到不到一半。</p>'),
     ('线上差别', '<p>恢复的 ClientHello 多一个 267 字节的 pre_shared_key,ServerHello 多 pre_shared_key,不再发证书。</p>'),
     ('1.2 恢复', '<p>完整 2 个往返,恢复 1 个:322 → 155 ms。</p>'),
     ('ticket 重复使用', '<p>同一个 ticket 连用 4 次都成功,但会让不同连接可被关联。</p>'),
     ('0-RTT', '<p>example.com 不允许早期数据,恢复成功但 early data 没发出。</p>')],
    steps,
    [ENV_W + '。对 example.com:443 的真实 TLS 连接(Python ssl + 抓包 en0,以及 Homebrew 的 openssl 4.0.3 s_client);耗时样本里有被网络抖动拉到 600~1500 ms 的离群值,所以只看中位数;Python 记录的 ticket 生存期(7200 秒)与服务器通告的(64800 秒)不同,我没有查原因',
     '没有验证:0-RTT 的收益和重放风险(服务器关闭了它);ticket 加密密钥的轮换;跨服务器(负载均衡后)的 ticket 共享;QUIC 的 0-RTT;TLS 1.3 的 PSK-only(不带 key_share)恢复模式;客户端不重用 ticket 的实现'],
    '会话恢复与 0-RTT')
